            customerType: PERSON
            firstNaming: "{{FirstNaming1}}"
            fullNaming: "{{FullNaming1}}"
            lastNaming: "{{LastNaming1}}"
            product: [
              {
                accountKey: "{{AccountKey1}}"
                accountName: "123AN"
                accountNumber: "321AN"
                transactionAmount: 100
                balance: 1200
                contractKey: "{{ContractKey1}}"
                transactionKey: "{{TransactionKey1}}"
                productType: CREDIT_CARD_PRODUCT
                customerKey: "{{CustomerKey1}}"
                customerBankingRelationshipKey: "{{CustomerBankingRelationshipKey1}}"
              }
            ]
          },
          graphModel: {
            edgeKey: "5dc3449a-f1c5-4e88-aada-a8e2dce37103"
            maxDepth: 1
            minDepth: 1
            recursive: true
            relationshipDirection: OUTGOING
            status: ACTIVE
          },
          outerCustomer: {
            customerKey: "{{CustomerKey2}}"
            customerType: PERSON
            firstNaming: "{{FirstNaming2}}"
            fullNaming: "{{FullNaming2}}"
            lastNaming: "{{LastNaming2}}"
            product: [
              {
                accountKey: "{{AccountKey2}}"
                accountName: "123AN2"
                accountNumber: "321AN2"
                transactionAmount: 1002
                balance: 12002
                contractKey: "{{ContractKey2}}"
                transactionKey: "{{TransactionKey2}}"
                productType: CREDIT_CARD_PRODUCT
                customerKey: "{{CustomerKey2}}"
                customerBankingRelationshipKey: "{{CustomerBankingRelationshipKey1}}"
              }
            ]
          },
          customerCustomerRelationshipKey: "{{CustomerBankingRelationshipKey1}}",
          innerCustomerKey: "{{CustomerKey1}}"
          outerCustomerKey: "{{CustomerKey2}}"
          customerCustomerRelationshipType: FAMILY
        }
      ]
      cacheKey: "2c0c7698-465f-4fbb-a8c1-9614f7ec6c05"
    }
    where: {
      customerCustomerEdge: {
        some: {
          innerCustomer: { customerKey: { in: "{{CustomerKey1}}" } }
          outerCustomer: { customerKey: { in: "{{CustomerKey2}}" } }
        }
      }
    }
  ) {
    edges {
      node {
        customerCustomerEdge {
          innerCustomer {
            customerKey
            customerType
            firstNaming
            fullNaming
            lastNaming
            product {
              contractKey
              accountName
              accountNumber
              transactionAmount
              balance
            }
          }
        }
      }
    }
  }
}

